2	 * Runtime point-table alarm compare (no I/O).
3	 *
4	 * Empty cmp, or ge/le with both thresholds missing, means no analog alarm.
5	 * Offline counts failures in the last 8 distinct samples (minimum 5).
6	 ****************************************************************************/
7	
8	#ifndef __APP_VELAGUARD_VG_ALARM_EVAL_H
9	#define __APP_VELAGUARD_VG_ALARM_EVAL_H
10	
11	#include <stdint.h>
12	
13	enum vg_alarm_kind
14	{
15	  VG_ALARM_KIND_NONE = 0,
16	  VG_ALARM_KIND_WARN,
17	  VG_ALARM_KIND_CRIT,
18	  VG_ALARM_KIND_OFFLINE
19	};
20	
21	struct vg_alarm_rule
22	{
23	  char cmp[4];
24	  uint8_t has_warn;
25	  uint8_t has_crit;
26	  float warn;
27	  float crit;
28	  uint8_t fail_n;
29	};
30	
31	struct vg_alarm_window
32	{
33	  uint8_t bits;
34	  uint8_t pos;
35	  uint8_t failures;
36	};
37	
38	/* Exactly one call per new acquisition sample. Successful reads always
39	 * recover offline state; threshold evaluation still uses the real value. */
40	enum vg_alarm_kind vg_alarm_sample(const struct vg_alarm_rule *rule,
41	                                   struct vg_alarm_window *window,
42	                                   int online, float value, float *thr_out);
43	
44	/* 0 = none. *thr_out is the threshold that fired (0 for offline). */
45	enum vg_alarm_kind vg_alarm_eval(const struct vg_alarm_rule *rule,
46	                                 int last_ok, uint8_t failed_samples,
47	                                 float value, float *thr_out);
48	
49	uint8_t vg_alarm_fail_n(const struct vg_alarm_rule *rule);
50	int vg_alarm_kind_rank(enum vg_alarm_kind kind);
51	
52	#endif
53

1	/****************************************************************************
2	 * app/velaguard/vg_alarm_eval.c
3	 ****************************************************************************/
4	
5	#include "vg_alarm_eval.h"
6	
7	#include <string.h>
8	
9	#ifndef VG_ALARM_EQ_EPS
10	#  define VG_ALARM_EQ_EPS 0.0005f
11	#endif
12	
13	uint8_t vg_alarm_fail_n(const struct vg_alarm_rule *rule)
14	{
15	  uint8_t n = rule ? rule->fail_n : 0;
16	  if (n < 5) return 5;
17	  if (n > 8) return 8;
18	  return n;
19	}
20	
21	enum vg_alarm_kind vg_alarm_sample(const struct vg_alarm_rule *rule,
22	                                   struct vg_alarm_window *window,
23	                                   int online, float value, float *thr_out)
24	{
25	  uint8_t mask;
26	  if (window == NULL) return VG_ALARM_KIND_NONE;
27	  mask = (uint8_t)(1u << (window->pos % 8));
28	  if (window->bits & mask) window->failures--;
29	  if (!online)
30	    { window->bits |= mask; window->failures++; }
31	  else window->bits &= (uint8_t)~mask;
32	  window->pos = (uint8_t)((window->pos + 1) % 8);
33	  return vg_alarm_eval(rule, online, window->failures, value, thr_out);
34	}
35	
36	int vg_alarm_kind_rank(enum vg_alarm_kind kind)
37	{
38	  switch (kind)
39	    {
40	      case VG_ALARM_KIND_CRIT:
41	        return 3;
42	      case VG_ALARM_KIND_OFFLINE:
43	        return 2;
44	      case VG_ALARM_KIND_WARN:
45	        return 1;
46	      default:
47	        return 0;
48	    }
49	}
50	
51	static int eq_hit(float value, float thr)
52	{
53	  float d = value - thr;
54	
55	  if (d < 0.0f)
56	    {
57	      d = -d;
58	    }
59	
60	  return d <= VG_ALARM_EQ_EPS;
61	}
62	
63	enum vg_alarm_kind vg_alarm_eval(const struct vg_alarm_rule *rule,
64	                                 int last_ok, uint8_t failed_samples,
65	                                 float value, float *thr_out)
66	{
67	  uint8_t need;
68	  const char *cmp;
69	
70	  if (thr_out != NULL)
71	    {
72	      *thr_out = 0.0f;
73	    }
74	
75	  if (rule == NULL)
76	    {
77	      return VG_ALARM_KIND_NONE;
78	    }
79	
80	  need = vg_alarm_fail_n(rule);
81	  if (!last_ok)
82	    {
83	      if (failed_samples >= need)
84	        {
85	          return VG_ALARM_KIND_OFFLINE;
86	        }
87	
88	      return VG_ALARM_KIND_NONE;
89	    }
90	
91	  cmp = rule->cmp;
92	  if (cmp[0] == '\0')
93	    {
94	      return VG_ALARM_KIND_NONE;
95	    }
96	
97	  if (strcmp(cmp, "eq") == 0)
98	    {
99	      if (rule->has_crit && eq_hit(value, rule->crit))
100	        {
101	          if (thr_out != NULL)
102	            {
103	              *thr_out = rule->crit;
104	            }
105	
106	          return VG_ALARM_KIND_CRIT;
107	        }
108	
109	      if (rule->has_warn && eq_hit(value, rule->warn))
110	        {
111	          if (thr_out != NULL)
112	            {
113	              *thr_out = rule->warn;
114	            }
115	
116	          return VG_ALARM_KIND_WARN;
117	        }
118	
119	      return VG_ALARM_KIND_NONE;
120	    }
121	
122	  if (strcmp(cmp, "ge") == 0)
123	    {
124	      if (rule->has_crit && value >= rule->crit)
125	        {
126	          if (thr_out != NULL)
127	            {
128	              *thr_out = rule->crit;
129	            }
130	
131	          return VG_ALARM_KIND_CRIT;
132	        }
133	
134	      if (rule->has_warn && value >= rule->warn)
135	        {
136	          if (thr_out != NULL)
137	            {
138	              *thr_out = rule->warn;
139	            }
140	
141	          return VG_ALARM_KIND_WARN;
142	        }
143	
144	      return VG_ALARM_KIND_NONE;
145	    }
146	
147	  if (strcmp(cmp, "le") == 0)
148	    {
149	      if (rule->has_crit && value <= rule->crit)
150	        {
151	          if (thr_out != NULL)
152	            {
153	              *thr_out = rule->crit;
154	            }
155	
156	          return VG_ALARM_KIND_CRIT;
157	        }
158	
159	      if (rule->has_warn && value <= rule->warn)
160	        {
161	          if (thr_out != NULL)
162	            {
163	              *thr_out = rule->warn;
164	            }
165	
166	          return VG_ALARM_KIND_WARN;
167	        }
168	
169	      return VG_ALARM_KIND_NONE;
170	    }
171	
172	  return VG_ALARM_KIND_NONE;
173	}
