void vg_runtime_init(void)
{
  if (g_inited)
    {
      return;
    }

  memset(g_pts, 0, sizeof(g_pts));
  memset(g_ev, 0, sizeof(g_ev));
  g_ev_pos = 0;
  g_ev_len = 0;
  g_boot_mono_ms = mono_ms();
  g_inited = 1;
  vg_fs_init();
}

uint32_t vg_runtime_uptime_s(void)
{
  uint32_t now;

  if (!g_inited)
    {
      vg_runtime_init();
    }

  now = mono_ms();
  if (now < g_boot_mono_ms)
    {
      return 0;
    }

  return (now - g_boot_mono_ms) / 1000u;
}

