              "第 %u 轮散布失败不应触发，实际 %s", i + 1, kind_name(kind));
        CHECK(window.failures <= 4,
              "第 %u 轮失败数应不超过 4，实际 %u", i + 1,
              (unsigned)window.failures);
      }
  }
}

